{
  "findings": [
    {
      "check_id": "CKV_SECRET_6",
      "title": "Plaintext secret in Terraform code",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "CRITICAL",
      "explanation": "The database connection string contains sensitive information (password) directly in the Terraform code."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  depends_on = [azurerm_mssql_database.legal_metadata_db]\n  content_type = \"text/plain\"\nsensitive = true\n}",
  "fix_summary": "Marked the azurerm_key_vault_secret resource as sensitive to prevent Terraform from displaying its value in the console output."
}
